def run(args):
    r = subprocess.run([sys.executable, T] + args, capture_output=True, text=True, encoding="utf-8")
    out = (r.stdout + r.stderr).strip()
    return r.returncode, out


if __name__ == "__main__":
    for name, pub, title, off, date in SOURCES:
        code, out = run(["source", "--name", name, "--publisher", pub, "--title", title, "--official", off, "--page-date", date])
        print(name, "->", out)
    ids = []
    for name, date, status, claim, quote, note in FACTS:
        a = ["add", "--prefix", "A", "--name", name, "--claim", claim, "--quote", quote, "--page-date", date, "--status", status]
        if note:
            a += ["--note", note]
        code, out = run(a)
        print(("OK " if code == 0 else "FAIL ") + out[:300], "|", claim[:80])
